  "challenge.definition.totalwar_doctrine.rule": "全程只能進行「全面戰爭」；劫掠與入侵被禁止。",
  "challenge.definition.totalwar_doctrine.summary": "只許發動全面戰爭，以最猛烈的手段碾碎一切。",
  "challenge.definition.totalwar_doctrine.tier.label": "核平",
  "challenge.definition.water_pollution.reward": "永久星屑產出 +10% · 商人奢侈品產出 +50% · 初始人口 +2",
  "challenge.definition.water_pollution.rule": "熱液能建築每秒排放與產出等值的汙染（星屑樹乘區不計）；汙染達 1000 / 4 萬 / 16 萬 / 640 萬依次進入濁流、赤潮、死區、腐淵，逐級扣幸福、削藻食與珊瑚，並按秒擲死亡；每名死者永久提高幸福消耗（墓地限額內 0.3%、超限 3%）。",
  "challenge.definition.water_pollution.summary": "熱液能產出即排汙，五個階段逐級侵蝕幸福、藻食與人口。",
  "challenge.definition.water_pollution.tier.label": "海淵澄明",
  "challenge.definition.weapon_critique.name": "武器的批判",
  "challenge.definition.weapon_critique.reward": "永久星屑獲取 +10% · 戰爭行動軍力消耗 -10%",
  "challenge.definition.weapon_critique.rule": "全程不得進行傳播文化 / 傳道信仰（軟實力），也不得修建貿易路線；戰爭行動與吞併不受限制。",
  "challenge.definition.weapon_critique.summary": "以武力推進文明，拒絕文化與信仰的滲透，也拒絕商路貿易。",
  "challenge.definition.weapon_critique.tier.label": "以武止戈",
  "challenge.job_limit.reason": "忽視科文挑戰限制：{jobName}已達 {cap} 人上限",
