  "challenge.notice.eternity_moment.progress": "天殼 {shellProgress}/{shellTarget} · 星空探索 {starProgress}/{starTarget} · 太陽帆 {sailCount}/{sailCap} · 戴森節點 {nodeCount}/{nodeCap}",
  "challenge.notice.eternity_moment.rule": "研究成本 ×{multiplier} · 冰殼、星空、太陽帆、戴森節點目標 ×{multiplier}",
