  "content.artwork.name": "藝術品",
  "content.artwork.short": "藝",
  "content.castle.building_upgrade_description": "每級降低所有建築下一級造價，且效果遞減；每級給{affectedEra}及之前有容量上限的資源增加{capacityBonus}容量，並使市政點產出增加{civicPointsPerSecondPerLevel}/級/秒。裝備政策卡「{policyCardName}」時，每級額外增加{faithProductionBonus}信仰產出。",
  "content.coral.name": "珊瑚",
  "content.coral.short": "珊",
  "content.craft_artwork.description": "把文明凝成可陳列的造物。歷史哲學的造物之一。",
  "content.craft_artwork.name": "藝術品",
  "content.craft_drill.description": "把鋼製零件、鈦與繩鍛成可以啃穿天殼的鑽頭。天穹鑽機的耗材。",
  "content.craft_drill.name": "共振鑽頭",
  "content.craft_hardcoral.description": "把珊瑚硬化成可承力的結構件。壓艙倉的建造成本之一。",
  "content.craft_hardcoral.name": "硬化珊瑚",
  "content.craft_ironbracket.description": "熱泉爐裡取出的支撐件。壓艙庫 / 藻食庫擴容的原料。",
  "content.craft_ironbracket.name": "鐵製支架",
  "content.craft_rocketengine.description": "燃料與封閉藻倉組裝成的火箭引擎。空間站的建造材料。",
  "content.craft_rocketengine.name": "火箭引擎",
  "content.craft_rocketfuel.description": "把暖石高壓精煉成火箭燃料。每{warmstonePerBatch}暖石出{fuelPerBatch}份燃料。",
  "content.craft_rocketfuel.name": "燃料",
  "content.craft_rope.description": "搓出來的捆紮件。壓艙庫 / 藻食庫擴容的原料。",
  "content.craft_rope.name": "繩",
  "content.craft_scaffold.description": "把硬化珊瑚與繩捆成作業面。天殼切削器的原料。",
  "content.craft_scaffold.name": "腳手架",
  "content.craft_sealbin.description": "用鈦金板件封住藻倉，存住溫水藻場。溫水藻場升級的材料。",
  "content.craft_sealbin.name": "封閉藻倉",
