  "content.craft_steelpart.name": "鋼製零件",
  "content.craft_stonebeam.description": "把石頭鑿成可搬運的梁。暫時供海潮方碑使用，以後給更多建築。",
  "content.craft_stonebeam.name": "石樑",
  "content.craft_strongprop.description": "行星際航行解鎖的工藝製造：燃料{fuelAmount}+ θ金屬{thetaMetalAmount}合成{engineCount}枚強工質火箭引擎。",
  "content.craft_thinafilm.description": "把 θ生物金屬壓成自適應薄膜。每{thetaMetalPerBatch}θ 出{filmPerBatch}卷薄膜（魔魚世界VR 的建造材料）。",
  "content.craft_tidal_record.description": "把潮紋讀成可傳承的知識。歷史哲學的造物之一。",
