  "game.story.unlock.civics.action": "進入市政頁",
  "game.story.unlock.civics.line_1": "這是鮫人們第一次圍坐在同一張石桌旁。",
  "game.story.unlock.civics.line_2": "集中食物、分配任務、解決分歧……文明從這裡開始。",
  "game.story.unlock.civics.system_description": "現在可以研究市政、選擇政體，並裝配政策卡。",
  "game.story.unlock.civics.system_title": "市政系統已開放",
  "game.story.unlock.civics.title": "市政頁解鎖",
  "game.story.unlock.company.action": "進入公司頁",
  "game.story.unlock.company.line_1": "我們吃生物合成的魚卵，吃在實驗室裡生長的海藻，該死，連光合作用都被註冊了！",
  "game.story.unlock.company.system_description": "系統自動成立藻食與珊瑚兩家公司，隨成立時間成長，提供對應資源產出加成。",
  "game.story.unlock.company.system_title": "公司系統已開放",
  "game.story.unlock.company.title": "公司頁解鎖",
  "game.story.unlock.diplomacy.action": "進入外交頁",
  "game.story.unlock.diplomacy.line_1": "軍事上得不到的，也休想在談判桌上得到。",
  "game.story.unlock.diplomacy.system_description": "現在可以劫掠、入侵、發動全面戰爭；逐階吞併七個敵國，每吞併一國，本局全域性產出都會永久提升。",
  "game.story.unlock.diplomacy.system_title": "七階敵國戰役已開放",
  "game.story.unlock.diplomacy.title": "外交頁解鎖",
  "game.story.unlock.faith.action": "進入信仰頁",
  "game.story.unlock.faith.line_1": "祭司把潮汐、族民與深海火光刻在同一張薄石板上。",
  "game.story.unlock.faith.line_2": "但為何每一位祭司對此都有不同的理解呢？",
  "game.story.unlock.faith.system_description": "現在可以檢視信仰產出、全域性加成，併為你的宗教命名。",
  "game.story.unlock.faith.system_title": "信仰系統已開放",
  "game.story.unlock.faith.title": "信仰頁解鎖",
  "game.story.unlock.prestige.action": "瞭解",
  "game.story.unlock.prestige.line_1": "鮫人的誦經聲伴隨深海的浪潮傳遍王國的角落，",
  "game.story.unlock.prestige.line_2": "祭司們說週期性的暖流與浪潮象徵著文明的輪迴……",
  "game.story.unlock.prestige.line_3": "從此，每一次終結這一局都將開啟一段新的輪迴——輪迴點可在輪迴商店換取永恆的增益。",
  "game.story.unlock.prestige.title": "輪迴系統解鎖",
  "game.story.unlock.star_map.action": "進入星圖頁",
  "game.story.unlock.star_map.line_1": "自鮫人首次抬頭望向頭頂的天殼，已經過去了不知多少歲月。",
  "game.story.unlock.star_map.line_2": "但在今天，他們首次望見了冰層後閃熠的群星。",
  "game.story.unlock.star_map.system_description": "現在可以檢視歐羅巴、土星，以及本週目已經發射的衛星和空間站。",
  "game.story.unlock.star_map.system_title": "星圖系統已開放",
  "game.story.unlock.star_map.title": "星圖頁解鎖",
  "game.story.unlock.technology.action": "進入科技頁",
  "game.story.unlock.technology.line_1": "鮫人將細小堅韌的深海藻類打了個結，「這代表今天，」他說。",
  "game.story.unlock.technology.line_2": "隨後，他又打了第二個結，「這代表明天。」",
  "game.story.unlock.technology.title": "科技頁解鎖",
  "game.story.unlock.wonder.action": "進入奇觀頁",
  "game.story.unlock.wonder.line_1": "十餘名石工師把藍圖攤在石臺上，最終成品的線條一路越過了整座巢穴。",
  "game.story.unlock.wonder.system_description": "現在可以檢視並建造獨特奇觀；建成後將永久留存並提供增益。",
  "game.story.unlock.wonder.system_title": "奇觀藍圖已揭曉",
  "game.story.unlock.wonder.title": "奇觀頁解鎖",
  "game.story.unlock.workshop.action": "進入工坊",
  "game.story.unlock.workshop.line_1": "砧、錘、繩索與熟稔運用的匠人。",
  "game.story.unlock.workshop.line_2": "如果一件工具能替我們重複昨天的動作，是不是也能用來做新的創造？",
  "game.story.unlock.workshop.system_description": "現在可以製造工藝品、購買職業工具，並安裝永久升級。",
  "game.story.unlock.workshop.system_title": "工藝製作已開放",
  "game.story.unlock.workshop.title": "工坊頁解鎖",
