  "tech.crewed.name": "載人航天",
  "tech.crewed.unlock_desc": "解鎖工坊配方「火箭引擎」、工坊升級「可控爆炸工藝」（工藝效率 ×{craftingMultiplier}），以及奇觀「上帝之杖」。",
  "tech.deepspace.name": "深空力學",
  "tech.deepspace.unlock_desc": "解鎖奇觀「旅行者一號」：星空進度未滿{thresholdPercent} 時每秒 {earlyExplorationRate}星空探索，滿{thresholdPercent} 後轉為 {lateExplorationRate}且學者產出 {scholarBonus}。",
  "tech.drift_tech.name": "流浪泰拉",
