  "tech.ecological_restoration.name": "生態重塑",
  "tech.ecological_restoration.unlock_desc": "解鎖奇觀「星球重構機 G.E.E.K」。完成恩克拉多斯星改造後，人口/速生珊瑚林/礦井/生息區建築升級消耗回到{levelThreshold}級之前。",
  "tech.education.name": "教育",
  "tech.education.unlock_desc": "解鎖研究所升級「大學」（學者科技產出 {perLevelPercent}/級）和奇觀「阿爾巴達熱液大學」。",
