  "ui.heritage.title": "傳承",
  "ui.intro.achievements.description": "文明里程碑收藏牆。",
  "ui.intro.achievements.title": "這是什麼 · 成就",
  "ui.intro.challenges.description": "給周目附加全域性規則的自限玩法：禁保溫、壓人口、限崗位、限時間等，規則越難，通關後給的永久獎勵越強。",
  "ui.intro.challenges.title": "這是什麼 · 挑戰",
  "ui.intro.civic.description": "按紀元推進的市政樹，科技會解鎖建築、政體與政策卡。",
  "ui.intro.civic.step": "1. 政體有不同的被動與政策槽數量，越後期的政體槽數量越多。<br>其次， 政策卡必須填入政策槽中才能發揮作用。",
  "ui.intro.civic.title": "這是什麼 · 市政",
  "ui.intro.company.description": "文明的經濟實體層（ERA{eraNumber} 市政《宏觀經濟學》解鎖）：系統自動成立藻食與珊瑚兩家公司，隨成立時間從鄉鎮成長為地方、全國企業，提供對應資源產出加成，同時恆增 {luxuryConsumptionIncreasePercent} 奢侈品消耗。",
  "ui.intro.company.title": "這是什麼 · 公司",
  "ui.intro.diplomacy.description": "完成《導航》科技後開放，與其他國家進行交流。",
  "ui.intro.diplomacy.step": "1. 用<b>劫掠 / 入侵 / 全面戰爭</b>削減敵國規模，行動消耗<b>軍力儲備</b>，軍人可能陣亡。<br>2. 規模歸零即可<b>吞併</b>；敵國也會反過來入侵，被攻入會損失材料、人口或建築等級。",
  "ui.intro.diplomacy.title": "這是什麼 · 外交",
  "ui.intro.faith.description": "信仰系統：研究《神學》後開放，信仰點驅動宗教加成。",
  "ui.intro.faith.step": "1. 每個輪迴的信仰存量會積累為舊日信仰，在每個輪迴都會發揮作用。<br>其次， 在解鎖神學，建立宗教後，輪迴可以獲得輪迴點。",
  "ui.intro.faith.title": "這是什麼 · 信仰",
  "ui.intro.folk.description": "人口與職業層：族民吃藻食、住住房，可以被分配為採集者/採石工/學者等職業，驅動各類產出。",
  "ui.intro.folk.step": "人口頂到上限就建更多住房，藻食必須超過{kelpThreshold}才會有新增人口。",
  "ui.intro.folk.title": "這是什麼 · 族民",
  "ui.intro.help.tooltip": "這是什麼？",
  "ui.intro.meta.description": "跨周目成長層：破殼結算給輪迴點，繁星結算給星屑在商店換永久增益。",
  "ui.intro.meta.step": "解鎖神學後才能獲得輪迴點，破殼後才會獲得星屑。",
  "ui.intro.meta.title": "這是什麼 · 輪迴商店",
  "ui.intro.star_dome.description": "跨周目局外資源層：星屑在輪迴結算時按太空與異星設施、星空探索和戴森球進度發放，可購買永久強化，也能與輪迴點按固定匯率互換。",
  "ui.intro.star_dome.step": "建成首座軌道衛星即可永久解鎖本頁；之後即使進入新周目、衛星等級歸零，商店仍保持開放。星屑在合格輪迴結算時入賬。",
  "ui.intro.star_dome.title": "這是什麼 · 星屑商店",
  "ui.intro.star_map.description": "破殼後解鎖的星空探索檢視，前期為母星所在行星系，後期會解鎖恆星系介面。",
  "ui.intro.star_map.step": "這裡的建築和巢穴標籤下星海區建築是一致的。",
  "ui.intro.star_map.title": "這是什麼 · 星圖",
  "ui.intro.tech.description": "按紀元推進的科技樹，科技會解鎖建築、資源線與後續系統；",
  "ui.intro.tech.step": "1. 每項科技內容起初是隱藏的，要達成尤里卡條件才會展示具體內容並可以研究。<br>其次， 研究完一個紀元的關鍵節點，就會展示下一個紀元科技的尤里卡，可以提前進行準備。",
  "ui.intro.tech.title": "這是什麼 · 科技",
  "ui.intro.village.description": "鮫人國度所有已經解鎖的建築列表，你可以在這裡對其進行升級。",
  "ui.intro.village.step": "使用手動「採藻食」、「採珊瑚」攢夠資源，建起深海藻場，礁口巢。",
  "ui.intro.village.title": "這是什麼 · 巢穴",
  "ui.intro.wonder.description": "大型工程專案：耗巨量資源建成，給全域性強增益或解鎖終局機制（如天穹鑽機）。",
  "ui.intro.wonder.title": "這是什麼 · 奇觀",
  "ui.intro.workshop.description": "把原料加工成進階物資，以及購買永久工藝升級。",
  "ui.intro.workshop.step": "工藝效率越高，消耗同樣材料獲得的進階物資就越多。",
  "ui.intro.workshop.title": "這是什麼 · 工坊",
